@startuml

class Location {
  + Address : string
}

class Driver {
  + FirstName : string
  + LastName : string
}

abstract class Vehicle {
  + VehicleNumber : string
}

class Truck extends Vehicle {
  + Weight : int
}

class Car extends Vehicle {
  + Seats : int
}

class Van extends Vehicle {
  + Capacity : int
}

class Order {
  + OriginLocation : Location
  + DestinationLocation : Location
  + AssignedDriver : Driver
  + ExecutionDate : date
}

Driver "1" -- "0..1" Order

Vehicle "0..*" -- "1" Driver

@enduml

